CALLS = [{"name": "bash", "arguments": {"command": "cat > paasio.py <<'PY'\nimport io\n\n\nclass MeteredFile(io.BufferedRandom):\n    \"\"\"A buffered random file that tracks IO usage.\"\"\"\n\n    def __init__(self, *args, **kwargs):\n        super().__init__(*args, **kwargs)\n        self._read_bytes = self._read_ops = 0\n        self._write_bytes = self._write_ops = 0\n\n    def __enter__(self):\n        return super().__enter__()\n\n    def __exit__(self, exc_type, exc_val, exc_tb):\n        return super().__exit__(exc_type, exc_val, exc_tb)\n\n    def __iter__(self):\n        return self\n\n    def __next__(self):\n        line = self.readline()\n        if not line:\n            raise StopIteration\n        return line\n\n    def read(self, size=-1):\n        data = super().read(size)\n        self._read_ops += 1\n        self._read_bytes += len(data)\n        return data\n\n    @property\n    def read_bytes(self):\n        return self._read_bytes\n\n    @property\n    def read_ops(self):\n        return self._read_ops\n\n    def write(self, b):\n        count = super().write(b)\n        self._write_ops += 1\n        self._write_bytes += count\n        return count\n\n    @property\n    def write_bytes(self):\n        return self._write_bytes\n\n    @property\n    def write_ops(self):\n        return self._write_ops\n\n\nclass MeteredSocket:\n    \"\"\"A socket proxy that tracks network IO usage.\"\"\"\n\n    def __init__(self, socket):\n        self.socket = socket\n        self._recv_bytes = self._recv_ops = 0\n        self._send_bytes = self._send_ops = 0\n\n    def __enter__(self):\n        self.socket.__enter__()\n        return self\n\n    def __exit__(self, exc_type, exc_val, exc_tb):\n        return self.socket.__exit__(exc_type, exc_val, exc_tb)\n\n    def recv(self, bufsize, flags=0):\n        data = self.socket.recv(bufsize, flags)\n        self._recv_ops += 1\n        self._recv_bytes += len(data)\n        return data\n\n    @property\n    def recv_bytes(self):\n        return self._recv_bytes\n\n    @property\n    def recv_ops(self):\n        return self._recv_ops\n\n    def send(self, data, flags=0):\n        count = self.socket.send(data, flags)\n        self._send_ops += 1\n        self._send_bytes += count\n        return count\n\n    @property\n    def send_bytes(self):\n        return self._send_bytes\n\n    @property\n    def send_ops(self):\n        return self._send_ops\nPY\npython3 - <<'PY'\nimport socket, tempfile\nfrom paasio import MeteredFile, MeteredSocket\nwith tempfile.TemporaryFile('w+b') as raw:\n    f = MeteredFile(raw)\n    assert f.write(b'abc') == 3\n    f.seek(0)\n    assert f.read(2) == b'ab'\n    assert (f.write_bytes, f.write_ops, f.read_bytes, f.read_ops) == (3, 1, 2, 1)\na, b = socket.socketpair()\nwith MeteredSocket(a) as m:\n    b.sendall(b'hello')\n    assert m.recv(5) == b'hello'\n    assert (m.recv_bytes, m.recv_ops) == (5, 1)\n    assert m.send(b'ok') == 2\n    assert b.recv(2) == b'ok'\n    assert (m.send_bytes, m.send_ops) == (2, 1)\nb.close()\nprint('IO accounting checks passed')\nPY", "timeout": 30}}]
